function(g, rect, comp, data, view) {
var imgMap = comp.getValue('imgMap'),
    textAlign = comp.getValue('textAlign'),
    value = comp.getValue('value'),
    gap = Number(comp.getValue('gap')) || 0,
    color = comp.getColor('color'),
    iconWidth = Number(comp.getValue('iconWidth')),
    iconHeight = Number(comp.getValue('iconHeight')),
    digitCount = Number(comp.getValue('digitCount')) || 0,
    fixed = Number(comp.getValue('fixed')) || 0;
var x = rect.x, y = rect.y, width = rect.width, height = rect.height;
var str = value == null ? '' : value + '';
var numericValue = Number(value);
if (str.indexOf('.') >= 0 && Number.isFinite(numericValue)) {
    str = numericValue.toFixed(fixed);
}
if (digitCount > str.length) {
    var pre = '';
    for (var i = 0; i < digitCount - str.length; i++) pre += '0';
    str = pre + str;
}
var ratio = iconHeight ? iconWidth / iconHeight : 0;
iconHeight = height;
iconWidth = ratio * iconHeight;
var strWidth = iconWidth * str.length + gap * Math.max(0, str.length - 1);
var tx = textAlign === 'center' ? x + (width - strWidth) / 2 : textAlign === 'right' ? x + width - strWidth : x;
for (var j = 0; j < str.length; j++) {
    var img = imgMap[str.charCodeAt(j)];
    if (img) comp.drawImage(g, img, tx, y, iconWidth, iconHeight, 'fill', color);
    tx += iconWidth + gap;
}
}
